from fastapi import FastAPI

from app.api.routes import claims
from app.core.errors import register_error_handlers

app = FastAPI(
    title="Claims Processing API",
    description="Insurance claims adjudication backend",
    version="1.0.0",
)

register_error_handlers(app)
app.include_router(claims.router)


@app.get("/")
def root():
    return {
        "success": True,
        "message": "Backend is running successfully",
    }


@app.get("/health")
def health_check():
    return {
        "status": "ok",
        "message": "Server is healthy",
    }

"""Claims adjudication routes."""

from __future__ import annotations

from fastapi import APIRouter

from app.schemas.claims import ClaimAdjudicationRequest, ClaimAdjudicationResponse
from app.services.claims_service import adjudicate_claim_request

router = APIRouter(prefix="/api/claims", tags=["claims"])


@router.post("/adjudicate", response_model=ClaimAdjudicationResponse)
def adjudicate(request: ClaimAdjudicationRequest) -> ClaimAdjudicationResponse:
    """Adjudicate a claim's line items against the supplied coverage rules."""
    return adjudicate_claim_request(request)
